mapper.select:
SELECT id, system_id AS systemId, file_name AS fileName, current_path AS currentPath, created_by AS createdBy, is_active AS isActive, created_time AS createdTime, updated_time AS updatedTime FROM institution_system_file WHERE system_id = #{systemId} AND keshi = #{keshi}
AND group_path = #{groupPath}
ORDER BY created_time DESC
